-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 8
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 8 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 08', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 08 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-08.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga o que é TDD (Test-Driven Development) e quando o teste é escrito.', 0.2, 'No **TDD (Test-Driven Development, desenvolvimento guiado por testes)** o teste é escrito **antes do código**: o teste descreve o próximo comportamento desejado e o código só existe para fazê-lo passar.', 'Palavras-chave: teste antes do código; teste descreve o comportamento. Nota cheia (0,2): definição com "antes". Metade (0,1): "desenvolver com testes" sem dizer quando. Zero (0): diz que o teste é escrito no fim.'),
      (v_atividade, 1, 2, 'Descreva as três fases do ciclo (vermelho, verde e refatorar), o que fazer em cada uma e como saber que ela terminou.', 0.4, '🔴 **Vermelho:** escrever **um** teste que falha — termina quando o Vitest mostra a falha **pelo motivo esperado**. 🟢 **Verde:** escrever o **mínimo** de código para passar — termina com **todos os testes verdes**. 🔵 **Refatorar:** melhorar nomes, tirar duplicação, extrair funções — termina quando **continua tudo verde**.', 'Palavras-chave: um teste que falha pelo motivo esperado; mínimo de código; todos verdes; refatorar sem quebrar. Nota cheia (0,4): as três fases com o que fazer e quando terminam. Metade (0,2): as três fases sem o critério de término, ou fora de ordem. Zero (0): fases erradas.'),
      (v_atividade, 1, 3, 'Escreva o comando que roda o Vitest em modo observação e explique por que ele ajuda a manter o ciclo curto.', 0.4, 'npx vitest (modo observação). Ele **roda os testes de novo a cada arquivo salvo**, então a resposta (vermelho ou verde) chega **em segundos**, sem precisar digitar comando, e o ciclo continua **curto (minutos)**.', 'Palavras-chave: npx vitest (sem run); roda a cada arquivo salvo; resposta rápida/ciclo curto. Nota cheia (0,4): comando + explicação. Metade (0,2): só o comando ou só a explicação. Zero (0): npx vitest run como modo observação, sem explicação.'),
      (v_atividade, 2, 1, 'Diga em qual das duas tarefas o TDD é indicado.', 0.2, 'Na **regra que valida o CPF** (lógica com comportamento verificável).', 'Palavras-chave: validação do CPF. Nota cheia (0,2): tarefa certa. Metade (0,1): as duas tarefas. Zero (0): só as cores do botão.'),
      (v_atividade, 2, 2, 'Cite três vantagens do TDD vistas na aula.', 0.4, '1) O código **já nasce testado**. 2) O projeto fica **simples**: só o necessário para os testes passarem. 3) O teste serve de **documentação do comportamento**.', 'Palavras-chave: nasce testado; simples/só o necessário; documentação. Nota cheia (0,4): as três vantagens. Metade (0,2): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 2, 3, 'Explique por que cores, espaçamentos e layout não são feitos com TDD e como eles são conferidos.', 0.4, 'Cores, espaçamentos e layout **não têm um resultado que um teste automatizado descreva bem antes do código** (o "certo" é visual e depende de quem olha). Eles são conferidos **visualmente** e com **testes de acessibilidade** (por exemplo, contraste), não com TDD.', 'Palavras-chave: resultado visual; conferência visual; testes de acessibilidade. Nota cheia (0,4): motivo + como conferir. Metade (0,2): só uma das partes. Zero (0): diz que layout se faz com TDD.'),
      (v_atividade, 3, 1, 'Diga por qual motivo o primeiro teste falha (fase vermelha) e por que é importante ver a falha pelo motivo esperado.', 0.2, 'Falha porque **a função validarCPF (e o arquivo) ainda não existe**. Ver a falha **pelo motivo esperado** prova que o teste **realmente testa** o comportamento e que ele vai ficar verde por causa do código novo, e não por acaso.', 'Palavras-chave: função não existe; motivo esperado prova que o teste testa algo. Nota cheia (0,2): motivo + importância. Metade (0,1): só o motivo. Zero (0): sem motivo correto.'),
      (v_atividade, 3, 2, 'Escreva o arquivo tests/validarCPF.test.js com os imports e o teste "rejeita valor vazio".', 0.4, 'import { describe, it, expect } from ''vitest''; import { validarCPF } from ''../src/validarCPF.js''; describe(''validarCPF'', () => { it(''rejeita valor vazio'', () => { expect(validarCPF('''')).toBe(false); }); });', 'Palavras-chave: import do vitest; import de validarCPF de ../src/validarCPF.js; validarCPF('''') com toBe(false). Nota cheia (0,4): arquivo completo. Metade (0,2): falta um dos imports ou o describe/it. Zero (0): sem expect.'),
      (v_atividade, 3, 3, 'Escreva o código mínimo que deixa esse teste verde e explique por que esse código, que parece trapaça, é proposital.', 0.4, 'export function validarCPF() { return false; } — É proposital porque o TDD pede o **mínimo de código** que faz o teste passar; o **próximo teste** (por exemplo, aceitar um CPF válido) é que **obriga o código a evoluir**. Assim, cada linha do código existe por causa de um teste.', 'Palavras-chave: return false; mínimo; o próximo teste obriga a evoluir. Nota cheia (0,4): código + explicação. Metade (0,2): só o código ou só a explicação. Zero (0): escreve a validação completa sem explicar o mínimo.'),
      (v_atividade, 4, 1, 'Escreva o teste do ciclo 2 ou do ciclo 3 (um caso inválido por formato ou por dígitos iguais).', 0.2, 'Um entre: it(''rejeita CPF com letras'', () => { expect(validarCPF(''529.982.247-2A'')).toBe(false); }); — it(''rejeita CPF com tamanho diferente de 11 dígitos'', () => { expect(validarCPF(''5299822472'')).toBe(false); }); — it(''rejeita CPF com todos os dígitos iguais'', () => { expect(validarCPF(''111.111.111-11'')).toBe(false); });', 'Palavras-chave: entrada inválida por letras, tamanho ou dígitos iguais; toBe(false). Nota cheia (0,2): teste correto. Metade (0,1): entrada certa sem verificação correta. Zero (0): espera true para entrada inválida.'),
      (v_atividade, 4, 2, 'Escreva os dois testes do ciclo 4: aceita 529.982.247-25 e rejeita 52998224726.', 0.4, 'it(''aceita CPF com dígitos verificadores corretos'', () => { expect(validarCPF(''529.982.247-25'')).toBe(true); }); it(''rejeita CPF com dígito verificador errado'', () => { expect(validarCPF(''52998224726'')).toBe(false); });', 'Palavras-chave: 529.982.247-25 com toBe(true); 52998224726 com toBe(false). Nota cheia (0,4): os dois testes. Metade (0,2): só um. Zero (0): valores trocados.'),
      (v_atividade, 4, 3, 'Um teste novo passou direto para o verde, sem mudar o código. Explique o que isso indica e o que fazer.', 0.4, 'Indica que o teste **não testava nada novo**: o comportamento já estava coberto pelos testes anteriores (ou o teste está errado e não falharia nunca). É preciso **rever o caso**: escolher uma entrada que exija código novo ou corrigir o teste para que ele falhe primeiro.', 'Palavras-chave: não testava nada novo; rever o caso. Nota cheia (0,4): o que indica + o que fazer. Metade (0,2): só uma parte. Zero (0): diz que é ótimo e segue sem rever.'),
      (v_atividade, 5, 1, 'Diga o que é o teste estrutural (caixa branca).', 0.2, 'É o teste que **olha o código por dentro** (as condições e os caminhos) para escolher os casos, de modo que **cada caminho** seja exercitado por algum teste.', 'Palavras-chave: olha o código/estrutura interna; caminhos/condições. Nota cheia (0,2): definição completa. Metade (0,1): "olha o código" sem falar dos caminhos. Zero (0): confunde com caixa preta.'),
      (v_atividade, 5, 2, 'Escreva um teste para cada caminho da condição resto < 2, usando 111.444.777-35 (caminho 11 - resto) e 123.456.789-09 (caminho do dígito 0).', 0.4, 'it(''aceita CPF que passa pelo caminho 11 - resto'', () => { expect(validarCPF(''111.444.777-35'')).toBe(true); }); it(''aceita CPF com primeiro dígito verificador 0'', () => { expect(validarCPF(''123.456.789-09'')).toBe(true); });', 'Palavras-chave: 111.444.777-35 com toBe(true); 123.456.789-09 com toBe(true). Nota cheia (0,4): os dois testes. Metade (0,2): só um. Zero (0): espera false nos dois.'),
      (v_atividade, 5, 3, 'Explique como olhar o código depois de cada verde ajuda a escolher o próximo teste.', 0.4, 'Depois de cada verde, olhar o código mostra **condições cujo outro lado nenhum teste exercita** (por exemplo, um if só testado no lado verdadeiro). **Esse lado é o próximo teste**: assim a suíte cobre todos os caminhos e encontra defeitos escondidos nos desvios.', 'Palavras-chave: if cujo outro lado não foi testado; esse é o próximo teste; cobrir todos os caminhos. Nota cheia (0,4): explicação completa. Metade (0,2): "para ter mais testes" sem falar do outro lado da condição. Zero (0): sem relação com o código.'),
      (v_atividade, 6, 1, 'Liste os cinco comportamentos do filtro, na ordem em que viram testes.', 0.2, '1) Sem texto digitado → **todos os produtos** aparecem. 2) Digitar **mouse** → só os produtos com "mouse" no título. 3) A busca **ignora maiúsculas e acentos** (TECLADO encontra "Teclado"). 4) **Categoria Periféricos + texto** → os dois filtros combinados. 5) Nada encontrado → mensagem **Nenhum produto encontrado**.', 'Palavras-chave: todos sem texto; filtra por texto; maiúsculas e acentos; categoria + texto; mensagem de nada encontrado. Nota cheia (0,2): os cinco em ordem. Metade (0,1): três ou quatro. Zero (0): dois ou menos.'),
      (v_atividade, 6, 2, 'Escreva o teste "digitar mouse mostra só os produtos com mouse no título", com o userEvent e a query getAllByRole(''listitem'').', 0.4, 'import { it, expect } from ''vitest''; import { screen } from ''@testing-library/dom''; import userEvent from ''@testing-library/user-event''; import { montarFiltro } from ''../src/montarFiltro.js''; const PRODUTOS = [{ titulo: ''Mouse sem fio'' }, { titulo: ''Teclado'' }, { titulo: ''Mouse gamer'' }]; it(''digitar mouse mostra só os produtos com mouse no título'', async () => { montarFiltro(document.body, PRODUTOS); await userEvent.type(screen.getByLabelText(''Buscar''), ''mouse''); const itens = screen.getAllByRole(''listitem''); expect(itens).toHaveLength(2); expect(itens[0]).toHaveTextContent(''Mouse sem fio''); });', 'Palavras-chave: montarFiltro com lista de produtos; userEvent.type no campo Buscar (getByLabelText ou getByRole(''textbox'', { name: ''Buscar'' })); await; getAllByRole(''listitem''); verificação da quantidade ou dos títulos. Nota cheia (0,4): teste completo. Metade (0,2): sem await, ou sem verificação da lista. Zero (0): sem digitar no campo.'),
      (v_atividade, 6, 3, 'Escreva o teste da mensagem "Nenhum produto encontrado" e explique por que os testes do componente usam o que o usuário vê.', 0.4, 'it(''mostra mensagem quando nada é encontrado'', async () => { montarFiltro(document.body, PRODUTOS); await userEvent.type(screen.getByLabelText(''Buscar''), ''monitor''); expect(screen.getByText(''Nenhum produto encontrado'')).toBeInTheDocument(); expect(screen.queryAllByRole(''listitem'')).toHaveLength(0); }); — Os testes usam **o que o usuário vê** (papel, rótulo, texto) para **não quebrar** quando o código interno ou o HTML mudam sem mudar o comportamento, e para conferir o que **realmente importa ao usuário**.', 'Palavras-chave: texto sem resultado; getByText(''Nenhum produto encontrado''); toBeInTheDocument; o que o usuário vê; não quebra com mudança interna. Nota cheia (0,4): teste + explicação. Metade (0,2): só o teste ou só a explicação. Zero (0): nenhum dos dois.'),
      (v_atividade, 7, 1, 'Diga o que ler primeiro na mensagem de falha.', 0.2, 'O que foi **esperado e o que foi recebido** (expected true, received false) e **a linha do teste** que falhou (nome do teste e arquivo).', 'Palavras-chave: esperado × recebido; linha/nome do teste. Nota cheia (0,2): as duas partes. Metade (0,1): só uma. Zero (0): nenhuma.'),
      (v_atividade, 7, 2, 'Escreva como isolar só esse teste com it.only e diga o que faz o describe.only.', 0.4, 'it.only(''aceita CPF com dígitos verificadores corretos'', () => { expect(validarCPF(''529.982.247-25'')).toBe(true); }); — O it.only roda **só aquele teste**; o describe.only roda **só aquele grupo** de testes.', 'Palavras-chave: it.only no teste que falha; describe.only = só o grupo. Nota cheia (0,4): código + explicação do describe.only. Metade (0,2): só uma das partes. Zero (0): usa it.skip ou apaga os outros testes.'),
      (v_atividade, 7, 3, 'Explique por que isolar o teste antes de procurar a causa economiza tempo.', 0.4, 'Com o teste isolado, a execução é **rápida** e a saída mostra **só aquela falha**, sem as mensagens dos outros 39 testes; cada mudança de investigação é conferida em segundos e a causa fica mais fácil de encontrar.', 'Palavras-chave: execução rápida; saída só da falha; menos ruído. Nota cheia (0,4): explicação com velocidade e foco. Metade (0,2): só uma das ideias. Zero (0): sem explicação.'),
      (v_atividade, 8, 1, 'Diga os passos para parar a execução numa linha do código com breakpoint no VS Code.', 0.2, 'Marcar o **breakpoint** clicando ao lado do número da linha; abrir **Run and Debug** → **JavaScript Debug Terminal**; rodar **npx vitest run** nesse terminal. O código **para na linha marcada**.', 'Palavras-chave: marcar a linha; JavaScript Debug Terminal; npx vitest run. Nota cheia (0,2): os passos. Metade (0,1): falta um passo. Zero (0): passos errados.'),
      (v_atividade, 8, 2, 'Explique o que o breakpoint mostra e como ele revelou que a função antiga usava resto <= 2, recusando todo CPF cujo dígito deveria ser 9.', 0.4, 'O breakpoint **para a execução** e mostra **o valor de cada variável** naquele momento (soma, resto, dígito). Parando no cálculo com um CPF cujo resto era **2**, você viu que a condição antiga (**resto <= 2**) dava **dígito 0**, quando o certo era **11 - 2 = 9**; por isso todo CPF com dígito 9 era recusado.', 'Palavras-chave: para a execução; mostra valores das variáveis; resto 2; <= dá 0 no lugar de 9. Nota cheia (0,4): o que mostra + como revelou o defeito. Metade (0,2): só uma das partes. Zero (0): sem relação com o breakpoint.'),
      (v_atividade, 8, 3, 'Escreva onde usar screen.debug() no teste do filtro e explique o que ele imprime.', 0.4, 'Logo depois da ação que muda a tela e antes da verificação que falha: montarFiltro(document.body, PRODUTOS); await userEvent.type(screen.getByLabelText(''Buscar''), ''mouse''); screen.debug(); — O screen.debug() **imprime no terminal o HTML atual** da tela do teste, mostrando o que o usuário "veria" naquele momento (quais itens a lista tem de verdade).', 'Palavras-chave: depois da ação e antes do expect; imprime o HTML atual do DOM. Nota cheia (0,4): lugar certo + explicação. Metade (0,2): só uma das partes. Zero (0): diz que ele corrige o teste.'),
      (v_atividade, 9, 1, 'Diga o que fazer com o it.only e com o console.log antes de entregar.', 0.2, '**Tirar o it.only** e **apagar o console.log** de depuração antes de entregar.', 'Palavras-chave: tirar it.only; apagar console.log. Nota cheia (0,2): os dois. Metade (0,1): só um. Zero (0): manter os dois.'),
      (v_atividade, 9, 2, 'Explique o que acontece com a suíte se o it.only for para o repositório.', 0.4, 'Com o it.only no repositório, **só aquele teste roda** e todos os outros são **pulados**, inclusive no pipeline: a suíte fica "verde" sem ter testado o resto do sistema, e defeitos novos **passam sem ninguém perceber**.', 'Palavras-chave: só um teste roda; os outros são pulados; defeitos passam despercebidos/falso verde. Nota cheia (0,4): explicação completa. Metade (0,2): "só roda um teste" sem a consequência. Zero (0): diz que não muda nada.'),
      (v_atividade, 9, 3, 'Descreva o passo final da depuração (corrigir e confirmar) e o que registrar no relatório da entrega.', 0.4, '**Corrigir e confirmar:** tirar o .only, **rodar a suíte inteira** e conferir que tudo está verde, depois **registrar a causa**. No relatório da entrega: **onde estava o defeito** (resto <= 2 no cálculo do dígito), **qual teste o revelou** e a tabela dos ciclos do TDD.', 'Palavras-chave: tirar .only; rodar a suíte inteira; registrar a causa; onde estava o defeito e qual teste revelou. Nota cheia (0,4): passo final + registro. Metade (0,2): só uma das partes. Zero (0): entrega sem rodar a suíte.'),
      (v_atividade, 10, 1, 'Cite três perguntas úteis para o code review de testes.', 0.2, 'Três entre: O nome do teste descreve o comportamento? O teste falharia se o código estivesse errado? Há casos de borda faltando? O teste depende de outro teste ou de dado externo? As queries seguem o comportamento visível? O que você aprendeu com este código?', 'Palavras-chave: as perguntas do cartão do code review. Nota cheia (0,2): três perguntas. Metade (0,1): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 10, 2, 'Reescreva com respeito o comentário "esse teste está horrível", com uma sugestão técnica concreta.', 0.4, 'Exemplo: "Gostei de os testes estarem separados por ciclo. Que tal testar também um CPF com dígito verificador 0, como 123.456.789-09? Assim cobrimos o outro caminho do resto < 2." (Valem outras sugestões técnicas, desde que comecem por um ponto concreto e sejam respeitosas, por exemplo "Que tal…".)', 'Palavras-chave: tom respeitoso (ex.: "Que tal…"); sugestão técnica concreta; fala do código, não da pessoa. Nota cheia (0,4): comentário respeitoso + sugestão concreta. Metade (0,2): respeitoso sem sugestão concreta, ou sugestão concreta com tom ofensivo. Zero (0): mantém a crítica pessoal.'),
      (v_atividade, 10, 3, 'Explique como quem recebe a sugestão deve avaliá-la e responder, e por que isso valoriza ideias diferentes (S1).', 0.4, 'Quem recebe avalia a sugestão pelo **fato técnico**, **não pela pessoa**, e responde **"aceito, porque…"** ou **"não vou aplicar, porque…"** com um argumento técnico. Isso **valoriza ideias diferentes** (S1): a sugestão é considerada pelo que ela melhora no código, e a equipe aprende com outros pontos de vista.', 'Palavras-chave: fato técnico, não a pessoa; aceito porque / não vou aplicar porque; valoriza ideias diferentes. Nota cheia (0,4): como avaliar + como responder + valor das ideias. Metade (0,2): só uma ou duas partes. Zero (0): manda ignorar a sugestão.');
end $$;
